@@ -0,0 +1,12 @@
+import { createEventCard } from "./event-card.js";
+import { summarizeAttendance } from "./attendance.js";
+import { sortChronologically } from "./agenda.js";
+
+export function buildOrganizerDigest(events, signupsByEvent = {}) {
+  const entries = events.map((event) => {
+    const card = createEventCard(event);
+    const signups = signupsByEvent && Object.hasOwn(signupsByEvent, card.id) ? signupsByEvent[card.id] : [];
+    return { event, summary: { ...card, ...summarizeAttendance(event, signups ?? []) } };
+  });
+  return sortChronologically(entries, (entry) => entry.event.startsAt).map((entry) => entry.summary);
+}

